import sys

def do_appear_in_some_cell(input_str):
    if len(input_str) < 3:
        return 'No'

    valid_set = {'ABC', 'ACB', 'BAC', 'BCA', 'CAB', 'CBA'}

    for i in range(len(input_str) - 2):
        substring = input_str[i:i+3]
        if substring in valid_set:
            return 'Yes'

    return 'No'

def main():
    input_data = sys.stdin.read().strip()
    # The problem expects a single line input, but read() gets all.
    # The original JS code reads line by line, but only uses the first line.
    # Using splitlines()[0] or just the whole stripped string works if input is single line.
    # However, CF inputs usually have newline at end.
    first_line = input_data.splitlines()[0] if input_data else ""
    result = do_appear_in_some_cell(first_line)
    sys.stdout.write(result)

if __name__ == "__main__":
    main()

